<script lang="ts">import{onMount}from'svelte';import type{EditorStore}from'../store.js';import type{PrinterSdk}from'../print/types.js';import{addElement,addFont,addResource}from'../commands.js';import{importAsset,importFont}from'../imports.js';import{uuid,type Resource,type FontResource}from'../model.js';import{AssetCatalogue,type CatalogueAsset}from'../catalogue.js';import{EditorDatabase}from'../persistence/database.js';import manifest from'../../../assets/public-catalogue.json';export let editor:EditorStore;export let sdk:PrinterSdk|undefined=undefined;const database=new EditorDatabase();let query='';let category='';let status='';let privateAssets:CatalogueAsset[]=[];let savedResources:Resource[]=[];let favorites=new Set<string>();let recents:string[]=[];let page=0;const pageSize=12;$:catalogue=new AssetCatalogue([...(manifest as CatalogueAsset[]).filter(item=>item.visibility==='public'),...privateAssets]);$:all=catalogue.search({query,category:category||undefined}).sort((a,b)=>recents.indexOf(b.id)-recents.indexOf(a.id));$:results=all.slice(page*pageSize,(page+1)*pageSize);$:pages=Math.max(1,Math.ceil(all.length/pageSize));
onMount(async()=>{const stored=await database.entries<unknown>('assets');privateAssets=stored.map(item=>item.value).filter((item):item is CatalogueAsset=>!!item&&typeof item==='object'&&'visibility'in item&&item.visibility==='private');savedResources=stored.map(item=>item.value).filter((item):item is Resource=>!!item&&typeof item==='object'&&'mimeType'in item&&'data'in item);favorites=new Set((await database.get<string[]>('preferences','asset-favorites'))??[]);recents=(await database.get<string[]>('preferences','asset-recents'))??[]});
async function remember(id:string){recents=[id,...recents.filter(item=>item!==id)].slice(0,24);await database.put('preferences','asset-recents',recents);await database.saveRecent({id,kind:'asset',openedAt:new Date().toISOString()})}async function favorite(id:string){favorites=new Set(favorites);favorites.has(id)?favorites.delete(id):favorites.add(id);await database.put('preferences','asset-favorites',[...favorites])}function place(resource:Resource,width=20,height=20){if(resource.mimeType.startsWith('font/')){editor.execute(addFont(resource as FontResource));return}editor.execute(addResource(resource));const base={id:uuid(),name:resource.name,resourceId:resource.id,transform:{x:2,y:2,width,height,rotation:0},zIndex:$editor.document.elements.length,visible:true,locked:false};editor.execute(addElement(resource.mimeType==='image/svg+xml'?{...base,type:'svg'}:{...base,type:'image',fit:'contain'}))}async function verifiedBytes(item:CatalogueAsset){const bytes=Uint8Array.from(atob(item.dataBase64??''),character=>character.charCodeAt(0));const digest=await crypto.subtle.digest('SHA-256',bytes);const hash=[...new Uint8Array(digest)].map(value=>value.toString(16).padStart(2,'0')).join('');if(hash!==item.sha256)throw new Error(`Catalogue hash mismatch for ${item.name}`);return bytes}async function use(item:CatalogueAsset){if(!item.dataBase64)return;await verifiedBytes(item);const resource={id:uuid(),name:item.name,mimeType:item.mediaType,sha256:item.sha256,data:item.dataBase64};place(resource);await database.saveAsset(resource);savedResources=[resource,...savedResources.filter(value=>value.sha256!==resource.sha256)];await remember(item.id);status=`Added ${item.name}`}async function collection(event:Event){try{const file=(event.currentTarget as HTMLInputElement).files?.[0];if(!file)return;const value=JSON.parse(await file.text())as CatalogueAsset[]|{assets:CatalogueAsset[]};const imported=(Array.isArray(value)?value:value.assets).map(item=>({...item,visibility:'private' as const,redistributionStatus:'private-only' as const}));for(const item of imported)await database.put('assets',`catalogue:${item.id}`,item);privateAssets=[...privateAssets,...imported];status=`Persisted ${imported.length} private assets locally.`}catch(error){status=String(error)}}async function asset(event:Event){const file=(event.currentTarget as HTMLInputElement).files?.[0];if(!file)return;try{const imported=await importAsset(file,sdk);place(imported.resource,imported.widthMm??20,imported.heightMm??20);await database.saveAsset(imported.resource);savedResources=[imported.resource,...savedResources.filter(value=>value.sha256!==imported.resource.sha256)];status=`Imported and placed ${file.name}`}catch(error){status=String(error)}}async function font(event:Event){const file=(event.currentTarget as HTMLInputElement).files?.[0];if(file){const imported=await importFont(file);editor.execute(addFont(imported));await database.saveAsset(imported);savedResources=[imported,...savedResources.filter(value=>value.sha256!==imported.sha256)]}}</script>
<section><h2>Asset catalogue</h2><input type="search" bind:value={query} on:input={()=>page=0} placeholder="Search catalogue"><select bind:value={category} on:change={()=>page=0}><option value="">All categories</option>{#each catalogue.categories as item}<option>{item}</option>{/each}</select><div class="actions"><label>Image/SVG/PDF<input type="file" accept="image/*,.svg,application/pdf" on:change={asset}></label><label>Font<input type="file" accept=".woff,.woff2,.ttf,.otf" on:change={font}></label><label>Private .mb-assets<input type="file" accept=".mb-assets,application/json" on:change={collection}></label></div><p aria-live="polite">{status}</p><ul>{#each results as item}<li>{#if item.dataBase64&&item.mediaType==='image/svg+xml'}<img alt="" src={`data:image/svg+xml;base64,${item.dataBase64}`}>{/if}<button class="star" aria-label={`Favorite ${item.name}`} aria-pressed={favorites.has(item.id)} on:click={()=>favorite(item.id)}>★</button><button on:click={()=>use(item)}>{item.name}</button><small>{item.kind} · {item.category} · {item.visibility}{recents.includes(item.id)?' · recent':''}</small></li>{/each}{#each savedResources.filter(item=>item.name.toLowerCase().includes(query.toLowerCase())) as item}<li><span>▧</span><button on:click={()=>place(item)}>Place {item.name}</button><small>{item.mimeType} · persisted private library</small></li>{/each}</ul><nav><button on:click={()=>page--} disabled={page===0}>Previous</button><span>{page+1}/{pages}</span><button on:click={()=>page++} disabled={page+1>=pages}>Next</button></nav></section>
<style>section{padding:.75rem;border-top:1px solid #ddd}h2{font-size:.8rem;text-transform:uppercase}.actions{display:flex;gap:.3rem;flex-wrap:wrap}.actions label{border:1px solid #bbb;padding:.3rem}.actions input{position:absolute;opacity:0;width:1px}ul{list-style:none;padding:0;max-height:24rem;overflow:auto}li{display:grid;grid-template-columns:2rem auto 1fr;gap:.2rem;align-items:center}li img{width:2rem;height:2rem}.star{grid-row:span 2}small{color:#666}nav{display:flex;justify-content:space-between}</style>
